// Export and copy (spec section 4): PNG at 1x, 2x and 4x, SVG, and Copy image, all made
// on the device from Indigo's rendering of the drawing (src/panels/exportImage.ts).
import type { Page } from '@playwright/test';
import { readFileSync } from 'node:fs';
import { crc32 } from 'node:zlib';
import { AT_CSS_PIXELS } from '../src/panels/exportImage.ts';
import {
  bondLengthInSvg,
  clearCanvas,
  cssPixels,
  expect,
  fixture,
  goOffline,
  ketcherSettings,
  openEditor,
  referenceCompound,
  test,
  type App,
} from './fixtures.ts';

/** A reference compound's Molfile, generated by RDKit (tests/fixtures/). */
function molfile(typedName: string): string {
  return fixture(referenceCompound(typedName).files.find((f) => f.endsWith('.mol'))!);
}

async function loadCompound(page: Page, typedName: string): Promise<void> {
  await page.evaluate((mol) => window.ketcher!.setMolecule(mol), molfile(typedName));
}

/** Indigo's SVG of the current drawing at CSS pixels, asked for directly through Ketcher's API. */
async function indigoSvg(page: Page): Promise<string> {
  return page.evaluate(async (atCssPixels) => {
    const ketcher = window.ketcher!;
    return (await ketcher.generateImage(await ketcher.getKet(), { outputFormat: 'svg', ...atCssPixels })).text();
  }, AT_CSS_PIXELS);
}

/** A bond in an SVG is as long as Ketcher's bond length setting at print size: ACS's
 * 14.4 pt is 0.2 in, 19.2 CSS px. (Ketcher's own ACS image resolution, 600 dpi, would draw
 * it 6.25 times that.) */
async function expectPrintSize(page: Page, svg: string): Promise<void> {
  const { bondLength, bondLengthUnit } = await ketcherSettings(page);
  expect(bondLengthUnit).toBe('pt');
  expect(bondLengthInSvg(svg)).toBeCloseTo(cssPixels(bondLength as number, bondLengthUnit as string), 0);
}

function exportDialog(page: Page) {
  return page.getByRole('dialog', { name: 'Export image' });
}

/** Wait for `step`, but fail at once if a guard trips first (a CSP report, a page error). */
function guarded<T>(app: App, step: Promise<T>): Promise<T> {
  return Promise.race([step, app.failed]);
}

let savedFiles = 0;

/** Click one of the export dialog's buttons; returns the file it downloads. */
async function downloadVia(app: App, button: string): Promise<{ name: string; bytes: Buffer }> {
  const click = exportDialog(app.page).getByRole('button', { name: button }).click();
  const [download] = await guarded(app, Promise.all([app.page.waitForEvent('download'), click]));
  const path = test.info().outputPath(`download-${++savedFiles}-${download.suggestedFilename()}`);
  await download.saveAs(path);
  return { name: download.suggestedFilename(), bytes: readFileSync(path) };
}

interface PngFacts {
  width: number;
  height: number;
  colorType: number;
  chunks: string[];
  /** From pHYs: pixels per metre, the unit (1 = metre), and whether its CRC is right. */
  phys: { x: number; y: number; unit: number; crcOk: boolean } | null;
}

/** A PNG's header and chunk list, read as the PNG spec lays them out. */
function pngFacts(bytes: Buffer): PngFacts {
  expect([...bytes.subarray(0, 8)]).toEqual([137, 80, 78, 71, 13, 10, 26, 10]);
  const chunks: string[] = [];
  let phys: PngFacts['phys'] = null;
  for (let at = 8; at < bytes.length; at += 12 + bytes.readUInt32BE(at)) {
    const type = bytes.toString('ascii', at + 4, at + 8);
    chunks.push(type);
    if (type === 'pHYs') {
      phys = {
        x: bytes.readUInt32BE(at + 8),
        y: bytes.readUInt32BE(at + 12),
        unit: bytes[at + 16],
        crcOk: bytes.readUInt32BE(at + 17) === crc32(bytes.subarray(at + 4, at + 17)),
      };
    }
  }
  expect(chunks[0]).toBe('IHDR');
  return { width: bytes.readUInt32BE(16), height: bytes.readUInt32BE(20), colorType: bytes[25], chunks, phys };
}

/** Decode a PNG in the browser: its top-left pixel and counts of pixel kinds. */
async function pngPixels(page: Page, bytes: Buffer) {
  return page.evaluate(async (base64) => {
    const data = Uint8Array.from(atob(base64), (char) => char.charCodeAt(0));
    const bitmap = await createImageBitmap(new Blob([data], { type: 'image/png' }));
    const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
    const context = canvas.getContext('2d', { willReadFrequently: true })!;
    context.drawImage(bitmap, 0, 0);
    const rgba = context.getImageData(0, 0, bitmap.width, bitmap.height).data;
    let opaque = 0;
    let notWhite = 0;
    for (let i = 0; i < rgba.length; i += 4) {
      if (rgba[i + 3] === 255) opaque++;
      if (rgba[i + 3] > 0 && (rgba[i] < 255 || rgba[i + 1] < 255 || rgba[i + 2] < 255)) notWhite++;
    }
    return { corner: [...rgba.subarray(0, 4)], opaque, notWhite, total: rgba.length / 4 };
  }, bytes.toString('base64'));
}

/** Parse an SVG in the browser: whether it is well formed, its size, what it draws. */
async function svgFacts(page: Page, text: string) {
  return page.evaluate((svg) => {
    const doc = new DOMParser().parseFromString(svg, 'image/svg+xml');
    const root = doc.documentElement;
    const shapes = [...root.querySelectorAll('path, use, line, polygon, polyline, ellipse, circle, rect')];
    return {
      errors: doc.getElementsByTagName('parsererror').length,
      root: root.localName,
      namespace: root.namespaceURI,
      width: Number(root.getAttribute('width')),
      height: Number(root.getAttribute('height')),
      // Glyph outlines live in <defs>; bonds and the uses of glyphs are drawn outside it.
      drawn: shapes.filter((el) => !el.closest('defs')).length,
    };
  }, text);
}

/** What the clipboard holds: each item's types, and its PNG if it has one. */
async function clipboardContents(page: Page) {
  const items = await page.evaluate(async () => {
    const read = await navigator.clipboard.read();
    return Promise.all(
      read.map(async (item) => {
        if (!item.types.includes('image/png')) return { types: item.types, png: '' };
        const bytes = new Uint8Array(await (await item.getType('image/png')).arrayBuffer());
        let binary = '';
        for (const byte of bytes) binary += String.fromCharCode(byte);
        return { types: item.types, png: btoa(binary) };
      }),
    );
  });
  return items.map((item) => ({ types: item.types, png: Buffer.from(item.png, 'base64') }));
}

function grantClipboard(app: App): Promise<void> {
  return app.context.grantPermissions(['clipboard-read', 'clipboard-write'], {
    origin: new URL(app.server.url).origin,
  });
}

/** Count the app's clipboard writes from here on. */
async function countClipboardWrites(page: Page): Promise<() => Promise<number>> {
  await page.evaluate(() => {
    const w = window as unknown as { __clipboardWrites: number };
    const clipboard = navigator.clipboard;
    const write = clipboard.write.bind(clipboard);
    w.__clipboardWrites = 0;
    clipboard.write = (items) => {
      w.__clipboardWrites += 1;
      return write(items);
    };
  });
  return () => page.evaluate(() => (window as unknown as { __clipboardWrites: number }).__clipboardWrites);
}

// 96, 192 and 384 dpi in pixels per metre (rounded), as PNG measures density.
const PER_METRE = { 1: 3780, 2: 7559, 4: 15118 } as const;

const EMPTY_EXPORT = 'Nothing to export: the drawing is empty.';
const FAILED_EXPORT = "Couldn't make the image. If the drawing is very large, try a smaller size.";

test('Export: PNG at 1x, 2x and 4x is exactly scale × the SVG, white unless transparent; the SVG is the drawing', async ({
  app,
}) => {
  const { page } = app;
  await openEditor(app);
  await loadCompound(page, 'caffeine');
  const expectedSvg = await indigoSvg(page);

  await page.getByTestId('app-export-button').click();
  const dialog = exportDialog(page);
  await expect(dialog.getByLabel('2x', { exact: true })).toBeChecked();

  const svgFile = await downloadVia(app, 'Download SVG');
  expect(svgFile.name).toBe('structure.svg');
  const svgText = svgFile.bytes.toString('utf8');
  await expectPrintSize(page, svgText);
  // Indigo's rendering of the drawing on the canvas, unchanged.
  expect(svgText).toBe(expectedSvg);
  const svg = await svgFacts(page, svgText);
  expect(svg).toMatchObject({ errors: 0, root: 'svg', namespace: 'http://www.w3.org/2000/svg' });
  expect([Number.isInteger(svg.width), Number.isInteger(svg.height)]).toEqual([true, true]);
  // An empty drawing renders as a 4×4 SVG with nothing drawn outside <defs> (measured).
  expect(svg.width * svg.height).toBeGreaterThan(16);
  expect(svg.drawn).toBeGreaterThan(0);

  for (const scale of [1, 2, 4] as const) {
    await dialog.getByLabel(`${scale}x`, { exact: true }).check();
    const png = await downloadVia(app, 'Download PNG');
    expect(png.name).toBe(scale === 1 ? 'structure.png' : `structure-${scale}x.png`);
    const facts = pngFacts(png.bytes);
    expect([facts.width, facts.height]).toEqual([svg.width * scale, svg.height * scale]);
    expect(facts.chunks.filter((type) => type === 'pHYs')).toEqual(['pHYs']);
    expect(facts.phys).toEqual({ x: PER_METRE[scale], y: PER_METRE[scale], unit: 1, crcOk: true });
    const pixels = await pngPixels(page, png.bytes);
    expect(pixels.corner).toEqual([255, 255, 255, 255]);
    expect(pixels.opaque).toBe(pixels.total);
    expect(pixels.notWhite).toBeGreaterThan(0);
  }

  await dialog.getByLabel('Transparent background (PNG)').check();
  const clear = await downloadVia(app, 'Download PNG');
  expect(clear.name).toBe('structure-4x.png');
  const clearFacts = pngFacts(clear.bytes);
  expect(clearFacts.colorType).toBe(6); // truecolour with alpha
  expect([clearFacts.width, clearFacts.height]).toEqual([svg.width * 4, svg.height * 4]);
  const clearPixels = await pngPixels(page, clear.bytes);
  expect(clearPixels.corner[3]).toBe(0);
  expect(clearPixels.notWhite).toBeGreaterThan(0);
  await expect(dialog.getByTestId('export-message')).toHaveText('');
});

test('pictures label what the canvas labels: heteroatoms with their hydrogens, no carbon labels', async ({ app }) => {
  // Hydrogens on heteroatoms only is the app's default (docs/plans/hetero-hydrogens.md, C);
  // Ketcher's own default also labels terminal carbons (CH3).
  const { page } = app;
  await openEditor(app);
  await loadCompound(page, 'paracetamol');
  const canvas = await page.evaluate(() => {
    const editor = window.ketcher!.editor;
    const svg = (editor as unknown as { render: { paper: { canvas: SVGSVGElement } } }).render.paper.canvas;
    const atoms = [...editor.struct().atoms.values()];
    return {
      // Ketcher draws each part of a label as its own text: "N", then "H".
      labels: [...svg.querySelectorAll('text')].map((text) => text.textContent ?? '').filter(Boolean),
      heteroatomsWithH: atoms.filter((atom) => atom.label !== 'C' && atom.implicitH > 0).length,
    };
  });
  expect(canvas.labels).not.toContain('C');
  expect(canvas.heteroatomsWithH).toBeGreaterThan(0);
  expect(canvas.labels.filter((text) => text === 'H')).toHaveLength(canvas.heteroatomsWithH);

  // Indigo draws a label's characters as uses of glyph outlines, one each. (Export's SVG is
  // this SVG, unchanged: the first test.)
  const glyphs = await page.evaluate((svg) => {
    const root = new DOMParser().parseFromString(svg, 'image/svg+xml').documentElement;
    return [...root.querySelectorAll('use')].filter((use) => !use.closest('defs')).length;
  }, await indigoSvg(page));
  expect(glyphs).toBe(canvas.labels.join('').length);
});

test('offline: Copy image puts a 2x PNG on the clipboard, and both downloads work', async ({ app }) => {
  const { context, page } = app;
  await grantClipboard(app);
  await goOffline(app);
  const failed: string[] = [];
  context.on('requestfailed', (request) => failed.push(request.url()));
  await loadCompound(page, 'caffeine');
  const caffeine = await svgFacts(page, await indigoSvg(page));

  const status = page.getByTestId('copy-status');
  await expect(status).toHaveAttribute('data-state', 'idle');
  await page.getByTestId('app-copy-image-button').click();
  await guarded(app, expect(status).toHaveAttribute('data-state', /^(done|empty|failed)$/));
  await expect(status).toHaveText('Image copied');
  const items = await clipboardContents(page);
  expect(items.map((item) => item.types)).toEqual([['image/png']]);
  const copied = pngFacts(items[0].png);
  expect([copied.width, copied.height]).toEqual([caffeine.width * 2, caffeine.height * 2]);
  const pixels = await pngPixels(page, items[0].png);
  expect(pixels.corner).toEqual([255, 255, 255, 255]);
  expect(pixels.notWhite).toBeGreaterThan(0);

  // "Image copied" is about the drawing that was copied: it goes when the drawing changes.
  await loadCompound(page, 'aspirin');
  await expect(status).toHaveAttribute('data-state', 'idle');
  await expect(status).toHaveText('');

  const expectedSvg = await indigoSvg(page);
  const svg = await svgFacts(page, expectedSvg);
  await page.getByTestId('app-export-button').click();
  expect((await downloadVia(app, 'Download SVG')).bytes.toString('utf8')).toBe(expectedSvg);
  const png = pngFacts((await downloadVia(app, 'Download PNG')).bytes);
  expect([png.width, png.height]).toEqual([svg.width * 2, svg.height * 2]);
  expect(failed).toEqual([]);
});

test('an empty drawing: nothing is copied or saved, and the student is told why', async ({ app }) => {
  const { page } = app;
  await grantClipboard(app);
  await openEditor(app);
  await clearCanvas(page);
  const downloads: string[] = [];
  page.on('download', (download) => downloads.push(download.suggestedFilename()));
  const clipboardWrites = await countClipboardWrites(page);

  await page.getByTestId('app-copy-image-button').click();
  await expect(page.getByTestId('copy-status')).toHaveText('Nothing to copy: the drawing is empty');

  await page.getByTestId('app-export-button').click();
  const dialog = exportDialog(page);
  const message = dialog.getByTestId('export-message');
  await dialog.getByRole('button', { name: 'Download PNG' }).click();
  await guarded(app, expect(message).toHaveText(EMPTY_EXPORT));
  // Opening the dialog again starts without a message.
  await dialog.getByRole('button', { name: 'Close' }).click();
  await page.getByTestId('app-export-button').click();
  await expect(message).toHaveText('');
  await dialog.getByRole('button', { name: 'Download SVG' }).click();
  await guarded(app, expect(message).toHaveText(EMPTY_EXPORT));

  expect(downloads).toEqual([]);
  expect(await clipboardWrites()).toBe(0);
});

test("a PNG the browser can't make: the student is told, nothing is saved, and SVG still works", async ({ app }) => {
  const { page } = app;
  await grantClipboard(app);
  await openEditor(app);
  await loadCompound(page, 'caffeine');
  // As when a big drawing at 4x is more than the browser's canvas can hold.
  await page.evaluate(() => {
    HTMLCanvasElement.prototype.toBlob = function (callback: BlobCallback) {
      callback(null);
    };
  });
  const downloads: string[] = [];
  page.on('download', (download) => downloads.push(download.suggestedFilename()));

  const status = page.getByTestId('copy-status');
  await page.getByTestId('app-copy-image-button').click();
  await guarded(app, expect(status).toHaveAttribute('data-state', /^(done|empty|failed)$/));
  await expect(status).toHaveText("Couldn't copy the image");

  await page.getByTestId('app-export-button').click();
  const dialog = exportDialog(page);
  await dialog.getByRole('button', { name: 'Download PNG' }).click();
  await guarded(app, expect(dialog.getByTestId('export-message')).toHaveText(FAILED_EXPORT));
  expect(downloads).toEqual([]);

  expect((await downloadVia(app, 'Download SVG')).name).toBe('structure.svg');
  await expect(dialog.getByTestId('export-message')).toHaveText('');
});

test('a browser that refuses the clipboard: the student is told, and the unread PNG raises no error', async ({
  app,
}) => {
  const { page } = app;
  await openEditor(app);
  await loadCompound(page, 'caffeine');
  // The browser refuses the write outright, so it never reads the PNG it was handed, and
  // that PNG fails too (as one too large for a canvas would). Its failure must not go
  // unhandled. Rejections are recorded here instead of tripping the page-error guard.
  await page.evaluate(() => {
    const w = window as unknown as { __unhandled: string[]; __pngFailed: Promise<void> };
    let failed!: () => void;
    w.__pngFailed = new Promise((resolve) => (failed = resolve));
    w.__unhandled = [];
    addEventListener('unhandledrejection', (event) => {
      event.preventDefault();
      w.__unhandled.push(event.reason instanceof Error ? event.reason.message : String(event.reason));
    });
    navigator.clipboard.write = () => Promise.reject(new DOMException('Write permission denied.', 'NotAllowedError'));
    HTMLCanvasElement.prototype.toBlob = function (callback: BlobCallback) {
      callback(null);
      failed();
    };
  });
  const status = page.getByTestId('copy-status');
  await page.getByTestId('app-copy-image-button').click();
  await guarded(app, expect(status).toHaveAttribute('data-state', /^(done|empty|failed)$/));
  await expect(status).toHaveText("Couldn't copy the image");

  // Once toBlob has answered null, the PNG has failed (in the same microtask checkpoint).
  // The browser reports unhandled rejections in the order they happen, so once a later,
  // deliberate one has been reported, an unhandled PNG failure would have been reported too.
  await page.evaluate(() => (window as unknown as { __pngFailed: Promise<void> }).__pngFailed);
  await page.evaluate(
    () =>
      new Promise<void>((resolve) => {
        addEventListener('unhandledrejection', (event) => {
          if (event.reason instanceof Error && event.reason.message === 'control') resolve();
        });
        void Promise.reject(new Error('control'));
      }),
  );
  expect(await page.evaluate(() => (window as unknown as { __unhandled: string[] }).__unhandled)).toEqual([
    'control',
  ]);
});

test('"Image copied" never shows for a drawing that changed while it was being copied', async ({ app }) => {
  const { page } = app;
  await grantClipboard(app);
  await openEditor(app);
  await loadCompound(page, 'caffeine');
  // Hold the clipboard write until the test lets it go.
  await page.evaluate(() => {
    const w = window as unknown as { __writeStarted: Promise<void>; __releaseWrite: () => void };
    const clipboard = navigator.clipboard;
    const write = clipboard.write.bind(clipboard);
    let started!: () => void;
    w.__writeStarted = new Promise((resolve) => (started = resolve));
    clipboard.write = (items) => {
      started();
      return new Promise((resolve, reject) => {
        w.__releaseWrite = () => void write(items).then(resolve, reject);
      });
    };
  });
  const status = page.getByTestId('copy-status');
  await page.getByTestId('app-copy-image-button').click();
  await page.evaluate(() => (window as unknown as { __writeStarted: Promise<void> }).__writeStarted);
  await expect(status).toHaveAttribute('data-state', 'copying');

  await loadCompound(page, 'aspirin'); // the drawing changes before the copy has finished
  await page.evaluate(() => (window as unknown as { __releaseWrite: () => void }).__releaseWrite());
  await guarded(app, expect(status).toHaveAttribute('data-state', /^(idle|done|empty|failed)$/));
  expect(await status.getAttribute('data-state')).toBe('idle');
  await expect(status).toHaveText('');
});

test("Ketcher's own image request for another drawing can't swallow the next one", async ({ app }) => {
  const { page } = app;
  await openEditor(app);
  await loadCompound(page, 'caffeine');
  // Indigo's worker answers in the order it is asked (src/editor/imageQueue.ts). Ask for
  // another drawing's image, as Ketcher's Save dialog preview does, and at once for this
  // drawing's; once the first has answered, ask for this drawing's again. Unqueued, the
  // first answer removes the second request's listener, so the second's answer goes to the
  // third request (same drawing), which settles while the second never does. Queued, the
  // third isn't even asked until the second has settled.
  const winner = await page.evaluate(async (other) => {
    const ketcher = window.ketcher!;
    const svg = { outputFormat: 'svg' as const };
    const ket = await ketcher.getKet();
    // Asked together, in one task: the worker can't have answered the first yet.
    const first = ketcher.generateImage(other, svg);
    const second = ketcher.generateImage(ket, svg).then(() => 'second');
    await first;
    const third = ketcher.generateImage(ket, svg).then(() => 'third');
    return Promise.race([second, third]);
  }, molfile('aspirin'));
  expect(winner).toBe('second');
});
